parameters.new_string:
function createErrorProvider(error: unknown): AIProvider {
  return {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw error;
    },

  it('error still propagates after onError hook', async () => {
    const hooks: OrchestratorHooks = {
      onError: async () => {},
    };

    const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
      hooks,
    });
    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('boom');
  });

  it('wraps non-Error rejections in an Error carrying cause and a readable message while rethrowing the original', async () => {
    const objectRejection = {code: 503, detail: 'upstream down'};
    const existingError = new AIError('already an error', 'UPSTREAM');

    const observe = async (thrown: unknown) => {
      const seenErrors: Error[] = [];
      const orchestrator = createChatOrchestrator(createErrorProvider(thrown), promptBuilder, undefined, {
        hooks: {
          onError: async (_session, error) => {
            seenErrors.push(error);
          },
        },
      });
      const turn = orchestrator.processMessage(createSession('hello'));
      const callerOutcome = await turn.then(
        reply => ({rejected: false, thrown: reply as unknown}),
        (caught: unknown) => ({rejected: true, thrown: caught})
      );
      const [firstError] = seenErrors;
      return {
        callCount: seenErrors.length,
        isError: firstError instanceof Error,
        causeMatches: firstError instanceof Error ? Object.is(firstError.cause, thrown) : false,
        hasCauseKey: firstError instanceof Error ? 'cause' in firstError : false,
        message: firstError instanceof Error ? firstError.message : '',
        sameErrorInstance: Object.is(firstError, thrown),
        callerOutcome,
      };
    };

    const [fromString, fromObject, fromUndefined, fromError] = await Promise.all([
      observe('string boom'),
      observe(objectRejection),
      observe(undefined),
      observe(existingError),
    ]);

    expect({fromString, fromObject, fromUndefined, fromError}).toEqual({
      fromString: {
        callCount: 1,
        isError: true,
        causeMatches: true,
        hasCauseKey: true,
        message: 'string boom',
        sameErrorInstance: false,
        callerOutcome: {rejected: true, thrown: 'string boom'},
      },
      fromObject: {
        callCount: 1,
        isError: true,
        causeMatches: true,
        hasCauseKey: true,
        message: "{ code: 503, detail: 'upstream down' }",
        sameErrorInstance: false,
        callerOutcome: {rejected: true, thrown: objectRejection},
      },
      fromUndefined: {
        callCount: 1,
        isError: true,
        causeMatches: true,
        hasCauseKey: true,
        message: 'undefined',
        sameErrorInstance: false,
        callerOutcome: {rejected: true, thrown: undefined},
      },
      fromError: {
        callCount: 1,
        isError: true,
        causeMatches: false,
        hasCauseKey: false,
        message: 'already an error',
        sameErrorInstance: true,
        callerOutcome: {rejected: true, thrown: existingError},
      },
    });
  });
});

